import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] l = new int[n];
        for (int i = 0; i < n; i++) {
            l[i] = Integer.parseInt(st.nextToken());
        }
        int[] firstPart = Arrays.copyOfRange(l, 0, n / 2);
        int[] secondPart = Arrays.copyOfRange(l, n / 2, n);
        int n1 = n / 2;
        int n2 = n / 2 + n % 2;
        int t1 = 1 << n1;
        int t2 = 1 << n2;
        List<Integer> s1 = new ArrayList<>();
        for (int i = 0; i < t1; i++) {
            int total = 0;
            for (int j = 0; j < firstPart.length; j++) {
                if ((i & (1 << j)) != 0) {
                    total += firstPart[j];
                }
            }
            s1.add(total % m);
        }
        List<Integer> s2 = new ArrayList<>();
        for (int i = 0; i < t2; i++) {
            int total = 0;
            for (int j = 0; j < secondPart.length; j++) {
                if ((i & (1 << j)) != 0) {
                    total += secondPart[j];
                }
            }
            s2.add(total % m);
        }
        Collections.sort(s1);
        Collections.sort(s2);
        int max_value = 0;

        for (int i : s1) {
            int needed = m - i;
            int pair = findClosest(s2, needed);
            max_value = Math.max(max_value, (i + pair) % m);
        }
        System.out.println(max_value);
    }

    private static int findClosest(List<Integer> list, int x) {
        int low = 0;
        int high = list.size() - 1;
        int answer = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < x) {
                answer = list.get(mid);
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return answer;
    }
}
